const { signInAccount, setSessionCookie } = vi.hoisted(() => ({
  signInAccount: vi.fn(),
  setSessionCookie: vi.fn(),
}));

vi.mock("@/server/services/auth-service", () => ({
  signInAccount,
}));

vi.mock("@/lib/session", () => ({
  setSessionCookie,
}));

describe("POST /api/v1/auth/login", () => {
  beforeEach(() => {
    signInAccount.mockReset();
    setSessionCookie.mockReset();
  });

describe("POST /api/v1/auth/login", () => {
  beforeEach(() => {
    signInAccount.mockReset();
    setSessionCookie.mockReset();
  });

  it("signs in an existing user and returns the redirect target", async () => {
    signInAccount.mockResolvedValue({
      userId: "user_123",
      redirectTo: "/circles/circle_123",
    });

    const response = await POST(
      new Request("http://localhost/api/v1/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: "amina@example.com",
        }),
      }),
    );

    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({
      redirectTo: "/circles/circle_123",
    });
    expect(setSessionCookie).toHaveBeenCalledWith(expect.anything(), "user_123");
  });

it("returns a not found error for unknown accounts", async () => {
  signInAccount.mockRejectedValue(
    new ServiceError(
      404,
      "ACCOUNT_NOT_FOUND",
      "No account exists for that email yet. Create one first.",
    ),
  );

  const response = await POST(
    new Request("http://localhost/api/v1/auth/login", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        email: "missing@example.com",
      }),
    }),
  );

  expect(response.status).toBe(404);
  expect(await response.json()).toEqual({
    error: {
      code: "ACCOUNT_NOT_FOUND",
      message: "No account exists for that email yet. Create one first.",
    },
  });
});

const { getSessionUserId, getCircleDashboardForUser } = vi.hoisted(() => ({
  getSessionUserId: vi.fn(),
  getCircleDashboardForUser: vi.fn(),
}));

vi.mock("@/lib/session", () => ({
  getSessionUserId,
}));

vi.mock("@/server/services/circle-dashboard-service", () => ({
  getCircleDashboardForUser,
}));

describe("GET /api/v1/circles/[circleId]", () => {
  beforeEach(() => {
    getSessionUserId.mockReset();
    getCircleDashboardForUser.mockReset();
  });

describe("GET /api/v1/circles/[circleId]", () => {
  beforeEach(() => {
    getSessionUserId.mockReset();
    getCircleDashboardForUser.mockReset();
  });

  it("returns 403 when no session is present", async () => {
    getSessionUserId.mockResolvedValue(null);

    const response = await GET(new Request("http://localhost"), {
      params: Promise.resolve({ circleId: "circle_123" }),
    });

    expect(response.status).toBe(403);
    expect(await response.json()).toEqual({
      error: {
        code: "AUTH_REQUIRED",
        message: "You need an active session.",
      },
    });
  });

it("returns the dashboard payload for an authorized member", async () => {
  getSessionUserId.mockResolvedValue("user_123");
  getCircleDashboardForUser.mockResolvedValue({
    circle: {
      id: "circle_123",
      name: "North Hill Community Circle",
      inviteCode: "AB8K2Q9L",
      approvalMode: "ADMIN_ONLY",
      minimumMonthlyContribution: 250,
      minimumMonthlyContributionFormatted: "$250.00",
      minimumReserveBalance: 1000,
      minimumReserveBalanceFormatted: "$1,000.00",
      minimumMembershipDurationMonths: 3,
      maxActiveLoansPerMember: 1,
      maxRepaymentTermMonths: 6,
      memberCount: 2,
    },
    viewerMembership: {
      role: "ADMIN",
      status: "ACTIVE",
    },
    members: [
      {
        id: "user_123",
        name: "Amina Yusuf",
        email: "amina@example.com",
        role: "ADMIN",
        status: "ACTIVE",
        joinedAt: "2026-04-01T00:00:00.000Z",
      },
    ],
  });

  const response = await GET(new Request("http://localhost"), {
    params: Promise.resolve({ circleId: "circle_123" }),
  });

  expect(response.status).toBe(200);
  expect(await response.json()).toMatchObject({
    circle: {
      id: "circle_123",
      name: "North Hill Community Circle",
    },
    viewerMembership: {
      role: "ADMIN",
    },
  });
  expect(getCircleDashboardForUser).toHaveBeenCalledWith("circle_123", "user_123");
});

