export async function upsertUser(
  db: DatabaseClient,
  input: {
    email: string;
    name: string;
  },
) {
  return db.user.upsert({
    where: { email: input.email },
    update: { name: input.name },
    create: input,
    select: {
      id: true,
      email: true,
      name: true,
    },
  });
}

export async function findUserByEmail(db: DatabaseClient, email: string) {
  return db.user.findUnique({
    where: { email },
    select: {
      id: true,
      email: true,
      name: true,
    },
  });
}

